@startuml

class Bus {
  + LicensePlateNumber : string[10]
}

class Driver {
  + Name : string
  + ID : int
  + OnSickLeave : boolean
}

class Route {
  + RouteNumber : int[4]
}

class Schedule {
  + ShiftType : string
  + Date : date
}

class BusOnRoute {
  + Bus : Bus
  + Route : Route
  + Schedule : Schedule
}

class RepairShop {
  + Name : string
  + Address : string
}

Bus "1" -- "*" BusOnRoute
Driver "1" -- "*" BusOnRoute
Route "1" -- "*" BusOnRoute

@enduml

